"use strict";
module.exports = /*#__PURE__*/JSON.parse('{"headline":"High-Fidelity SVG Animation to Video & Animated Image Studio","tagline":"Transform CSS-animated SVGs into MP4, WebM, MKV, MOV, aPNG, or GIF with full alpha-channel transparency — directly in your browser or via CLI/MCP.","features":[{"title":"Transparent Backgrounds","descriptionHtml":"Export your animations with a full alpha channel using <strong>WebM or aPNG</strong>, and optimized indexed transparency with <strong>GIF89a</strong>. Perfect for overlays in video editing tools or web use."},{"title":"Privacy-First","descriptionHtml":"The Web Studio runs entirely in your browser—your SVG files never leave your computer."},{"title":"Frame-Accurate","descriptionHtml":"Our engine scrubs the <strong>Web Animations API</strong>, ensuring every frame is captured exactly as rendered."},{"title":"AI Agent Native","descriptionHtml":"Native <strong>Model Context Protocol (MCP)</strong> server and <strong>Agent Skill (<code>SKILL.md</code>)</strong> support indexed on the official <a href=\\"https://registry.modelcontextprotocol.io/\\">MCP Registry</a> (<code>mcp.json</code>) and hosted live on <a href=\\"https://huggingface.co/spaces/GehDoc/svg-to-video-mcp\\">HuggingFace Spaces</a>."},{"title":"Universal Animated Formats","descriptionHtml":"Beyond video, generate lightweight <strong>Animated PNGs (aPNG)</strong> and <strong>GIFs</strong> perfect for documentation, Slack, or GitHub, with full control over background transparency."},{"title":"Copy to Clipboard","descriptionHtml":"Instant export to <strong>Base64 Data URL</strong>—copy your video and embed it directly into your HTML, CSS, or JS code without manual downloads. Perfect for rapid prototyping and developers."},{"title":"Metadata Injection","descriptionHtml":"Support for custom titles and comments across video (MP4, WebM, MKV, MOV) and animated image (aPNG, GIF) formats."},{"title":"Versatile","descriptionHtml":"Whether you need an accessible <a href=\\"#-web-studio\\">Web Studio</a> for quick conversions or a powerful <a href=\\"#-cli--docker-tool\\">CLI tool</a> for batch automation and CI/CD pipelines, this project has you covered."}],"quickStartSteps":["Open the <a href=\\"https://gehdoc.github.io/svg-to-video/\\">Web Studio</a>.","Drag and drop your <code>.svg</code> file, or test the engine instantly with 1-click built-in samples.","Adjust resolution, duration, and FPS.","Select your format, toggle <strong>Transparent Background</strong> if needed, and ensure <strong>High-Fidelity Capture</strong> is enabled for best results.","Click <strong>Export</strong>."],"cliSnippet":"# Node.js (auto-detected duration)\\nnpx -y -p @gehdoc/svg-to-video svg-to-video input.svg 60 ./out-dir\\n\\n# Node.js (explicit duration & GIF output)\\nnpx -y -p @gehdoc/svg-to-video svg-to-video input.svg 60 ./out-dir -d 5 --format gif --transparent\\n\\n# Node.js (custom resolution dimensions e.g. vertical 1080x1920)\\nnpx -y -p @gehdoc/svg-to-video svg-to-video input.svg 60 ./out-dir --width 1080 --height 1920\\n\\n# Node.js (animated PNG output)\\nnpx -y -p @gehdoc/svg-to-video svg-to-video input.svg 60 ./out-dir -d 5 --format apng\\n\\n# Docker (zero local dependencies; requires --shm-size=2gb for Chromium rendering; add :Z to -v for SELinux / Fedora)\\ndocker run --rm --shm-size=2gb -e PUPPETEER_ARGS=\\"--no-sandbox\\" -v $(pwd):/data:Z gehdoc/svg-to-video /data/input.svg 60 /data/out-dir -d 5 --format gif","mcpSnippet":"{\\n     \\"mcpServers\\": {\\n       \\"svg-to-video\\": {\\n         \\"command\\": \\"npx\\",\\n         \\"args\\": [\\"-y\\", \\"-p\\", \\"@gehdoc/svg-to-video\\", \\"svg-to-video-mcp\\"]\\n       }\\n     }\\n   }","formatComparisons":[{"format":"MP4","codec":"H.264 / AAC","transparency":"No (Opaque)","bestFor":"Universal web playback, social media, video editors (Premiere, Final Cut)","description":"Standard baseline container compatible with all browsers and video players."},{"format":"WebM","codec":"VP9 / AV1","transparency":"Yes (Full Alpha Channel)","bestFor":"Web overlays, OBS streaming, transparent video backgrounds","description":"Modern open web format with native 8-bit alpha transparency and high compression efficiency."},{"format":"aPNG","codec":"RGBA PNG","transparency":"Yes (Full Alpha Channel)","bestFor":"Documentation, GitHub READMEs, high-color animations, crisp text rendering","description":"Animated PNG with 24-bit color depth and full 8-bit alpha blending without color quantization."},{"format":"GIF","codec":"GIF89a","transparency":"Yes (Indexed 1-bit)","bestFor":"Slack, Discord, legacy documentation, universal messaging apps","description":"Standard animated GIF with palette quantization and optional transparent color index."}],"faq":[{"question":"Are my SVG files uploaded to any external server?","answerHtml":"No. The Web Studio runs 100% client-side inside your browser using WebCodecs and the Web Animations API. Your SVG source code and exported video frames never leave your local device."},{"question":"How does the Web Animations API frame scrubbing work?","answerHtml":"The engine mounts your SVG in an isolated offscreen canvas, programmatically pauses all CSS and SMIL animations, and advances the animation timeline frame by frame (e.g. at 24, 30, or 60 FPS) to guarantee 100% frame accuracy without skipped frames."},{"question":"Can I automate conversions in CI/CD pipelines or AI agents?","answerHtml":"Yes! You can use the official CLI tool (<code>npx -y @gehdoc/svg-to-video</code>), the Docker image (<code>gehdoc/svg-to-video</code>), or connect to the Model Context Protocol (MCP) server for Claude Desktop, Cursor, and Antigravity."},{"question":"How do I preserve transparent backgrounds in exported videos?","answerHtml":"Select <strong>WebM</strong>, <strong>aPNG</strong>, or <strong>GIF</strong> as your output format, check the &quot;Transparent Background&quot; toggle, and ensure your SVG root element does not declare an opaque background rect."}],"lastUpdated":"2026-10-14T20:09:26.810Z"}');

